class VisualObj {
	constructor(x, y, max_sze, clr, clrDest) {
		this.x = x; 
		this.y = y;
		this.vx = (noise(x/width, y/height, 10)-0.5) * 15; // random(-2, 2);
		this.vy = (noise(y/height, x/width, 20)-0.5) * 15; // random(-2, 2);
		this.ax = (noise(x/width, y/height, 30)-0.5) * 0.75; // random(-0.1, 0.1);
		this.ay = (noise(x/width, y/height, 40)-0.5) * 0.75; // random(-0.1, 0.1);
		this.n = random([3, 4, 6]); // n-edge
		this.sze = 1;
		this.max_sze = max_sze;
		this.d_sze = random(1.7, 2.3);
		this.ang = random(TAU);
		this.d_ang = random(0.025, 0.1) * Math.sign(random()-0.5);
		this.clr = clr;
		this.clrDest = clrDest;
		this.states = [];
		this.growing = true;
	} // constructor

	update() {
		if (this.sze < this.max_sze) {
			this.vx += this.ax;
			this.vy += this.ay;			
			this.x += this.vx;
			this.y += this.vy;

			this.sze += this.d_sze; 
			this.ang += this.d_ang; 

			if (!USE_SVG) this.clr = lerpColor(this.clr, this.clrDest, 0.05);
			this.states.push({
				x: this.x,
				y: this.y,
				sze: this.sze,
				ang: this.ang,
				clr: this.clr,
				stClr: adjColorBrightness(adjColorSaturation(this.clr, 1.5), 0.5)
			});

			// check if reached end
			if (this.sze >= this.max_sze) {
				this.growing = false;
				return true;
			}

		} else {
			this.growing = false;

		}

		return false;
	} // update()

	draw() {
		for (let i = this.states.length-1; i >= 0; i--) {
			const st = this.states[i];

			push();
			noStroke(); stroke(st.stClr);	strokeWeight(1.5);	
			fill(st.clr);
			if (USE_SVG) {
				noFill(); stroke(st.clr); strokeWeight(1); fill(BG);
			}
			translate(st.x, st.y);
			rotate(st.ang);

			if (this.n === 4) {
				rectMode(CENTER);
				rect(0, 0, st.sze);
			} else {				
				const r = st.sze/2;
				beginShape();
				for (let j = 0; j < this.n; j++) {
					const a = j / this.n * TAU;
					const x = cos(a) * r;
					const y = sin(a) * r;
					vertex(x, y);
				}
				endShape(CLOSE);
			}

			pop();
		}
	} // draw()

} // VisualObj class

