function drawBackground(bg) {
	if (USE_SVG) return drawBackgroundSvg(bg);

	push()
	const ctx = drawingContext;
	const gradient = ctx.createRadialGradient(
		width/2, height/2, max(width, height)/1000, 
		width/2, height/2, max(width, height)*0.65
	);
	gradient.addColorStop(0.3, bg);
	gradient.addColorStop(1, color(0, 16));

	// Set the fill style and draw a rectangle
	ctx.fillStyle = gradient;
	ctx.fillRect(0, 0, width, height);

	stroke(0, 50)
	strokeWeight(1.25)
	for (let y = 3; y < height; y += 4) {
		line(0, y, width, y)
	}

	pop()
}

function drawBackgroundSvg() {
	noFill();
	stroke(128);

	// 1
	if (false)
	for (let y=1, d=2; y<height; d+=2, y+=d) {
		line(0, height-y, width, height-y);
	}

	// 2
	if (true) {
		const d = height/20
		for (let y=d/2; y<height; y+=random(0.8, 1.2) * d) {
			line(0, y, width, y);
		}
	}

	return;

	// 3
	const cx = floor(width/2);
	const cy = floor(height/2);
	for (let o=10, i=o; i<width; i+=2, o+=i) {
		line(0, cy+o, width, cy+o);
		line(cx+o, 0, cx+o, height);
		if (i > 0) {
			line(0, cy-o, width, cy-o);
			line(cx-o, 0, cx-o, height);			
		}
		circle(cx, cy, o * 2)
	}
}
